from __future__ import annotations
import numpy as np

# ── ADAPTED GAME-SPECIFIC PRIORS ──────────────────────────────────────────
# Increased movable size to capture larger blocks/pieces.
_SKEL_MOVABLE_MAX_SIZE = 25 
_SKEL_SEARCH_DEPTH = 8
_SKEL_BRANCH = 4
_SKEL_NEAR = 8.0

def _skel_background(frame: np.ndarray) -> int:
    f = np.asarray(frame)
    if f.size == 0:
        return 0
    vals, counts = np.unique(f, return_counts=True)
    return int(vals[int(counts.argmax())])

def _skel_flood_regions(frame: np.ndarray, bg: int) -> list:
    f = np.asarray(frame)
    h, w = f.shape
    seen = [[False] * w for _ in range(h)]
    regions = []
    for y in range(h):
        for x in range(w):
            if seen[y][x]:
                continue
            seen[y][x] = True
            color = int(f[y, x])
            if color == bg:
                continue
            cells = [(y, x)]
            stack = [(y, x)]
            while stack:
                cy, cx = stack.pop()
                for ny, nx in ((cy - 1, cx), (cy + 1, cx), (cy, cx - 1), (cy, cx + 1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] \
                            and int(f[ny, nx]) == color:
                        seen[ny][nx] = True
                        cells.append((ny, nx))
                        stack.append((ny, nx))
            mx = sum(c[1] for c in cells) / len(cells)
            my = sum(c[0] for c in cells) / len(cells)
            regions.append({
                "color": color, "cells": cells, "size": len(cells),
                "cx": int(round(mx)), "cy": int(round(my)),
            })
    return regions

def _skel_classify(regions, trace=None):
    movable = [r for r in regions if r["size"] <= _SKEL_MOVABLE_MAX_SIZE]
    fixed = [r for r in regions if r["size"] > _SKEL_MOVABLE_MAX_SIZE]
    if trace is not None:
        trace.append(f"parse regions={len(regions)} movable={len(movable)} fixed={len(fixed)}")
    return movable, fixed

def _skel_learn_move(transitions, bg, trace=None):
    to_loc = 0
    click_piece = 0
    for t in transitions:
        xy = t.get("xy")
        if xy is None: continue
        before = np.asarray(t["before"])
        after = np.asarray(t["after"])
        if before.shape != after.shape: continue

        diff = np.where(before != after)
        if len(diff[0]) == 0: continue

        # Check if the click was on a piece that then moved
        before_color = before[int(xy[1]), int(xy[0])]
        if before_color != bg:
            click_piece += 1

        # Check if the piece moved toward the click
        d = abs(float(diff[1].mean()) - xy[0]) + abs(float(diff[0].mean()) - xy[1])
        if d <= _SKEL_NEAR:
            to_loc += 1

    mode = "to_location" if to_loc > click_piece else ("click_piece" if click_piece > 0 else "none")
    if trace is not None:
        trace.append(f"move-model to_loc={to_loc} click_piece={click_piece} -> {mode}")
    return mode

def _skel_plan_to_location(movers, targets, trace=None):
    tgt = [(t["cx"], t["cy"]) for t in targets]
    best = {"key": None, "assign": []}
    limit = min(len(movers), _SKEL_SEARCH_DEPTH)

    def leaf(cost, assign):
        key = (-len(assign), cost)
        if best["key"] is None or key < best["key"]:
            best["key"] = key
            best["assign"] = list(assign)

    def dfs(i, used, cost, assign):
        if i >= limit:
            leaf(cost, assign)
            return
        mx, my = movers[i]["cx"], movers[i]["cy"]
        order = sorted(range(len(tgt)), key=lambda j: abs(tgt[j][0] - mx) + abs(tgt[j][1] - my))
        placed = False
        for j in order[:_SKEL_BRANCH]:
            if j in used: continue
            placed = True
            used.add(j)
            assign.append(tgt[j])
            dfs(i + 1, used, cost + abs(tgt[j][0] - mx) + abs(tgt[j][1] - my), assign)
            assign.pop()
            used.discard(j)
        if not placed:
            dfs(i + 1, used, cost, assign)

    dfs(0, set(), 0.0, [])
    return best["assign"]

def simdfs_skel_core(current_frame, transitions, act, trace=None):
    frame = np.asarray(current_frame)
    bg = _skel_background(frame)
    regions = _skel_flood_regions(frame, bg)
    movers, fixed = _skel_classify(regions, trace)
    mode = _skel_learn_move(transitions, bg, trace)

    if mode == "to_location" and movers and fixed:
        plan = _skel_plan_to_location(movers, fixed, trace)
        for (x, y) in plan:
            act("CLICK", int(x), int(y))
        if plan: return

    if mode == "click_piece" and movers:
        clicked = {(int(t["xy"][0]), int(t["xy"][1])) for t in transitions if t.get("xy")}
        for r in movers:
            if (r["cx"], r["cy"]) not in clicked:
                act("CLICK", int(r["cx"]), int(r["cy"]))
                return
        act("CLICK", int(movers[0]["cx"]), int(movers[0]["cy"]))
        return

    clicked = {(int(t["xy"][0]), int(t["xy"][1])) for t in transitions if t.get("xy")}
    for r in movers:
        if (r["cx"], r["cy"]) not in clicked:
            if trace is not None: trace.append(f"probe piece ({r['cx']},{r['cy']})")
            act("CLICK", int(r["cx"]), int(r["cy"]))
            return

    if fixed:
        for r in fixed:
            if (r["cx"], r["cy"]) not in clicked:
                act("CLICK", int(r["cx"]), int(r["cy"]))
                return
